D=Path('/evidence/extended/playback-pipeline-01/blurriness');C=np.load(D/'candidate-complete.npy');crop=C[690-220:755-220,900-620:1040-620];lum=crop@np.array([.2126,.7152,.0722],np.float32);bp=(cv2.GaussianBlur(lum,(0,0),.5)-cv2.GaussianBlur(lum,(0,0),3.))[8:-8,8:-8]*255;z=json.loads((D/'candidate.json').read_text());texture=json.loads((D/'texture-analysis.json').read_text());result={'candidate_bandpass_RMS':float(np.sqrt(np.mean(bp**2))),'reference_bandpass_RMS':texture['reference']['bandpass_RMS'],'unblurred_bandpass_RMS':texture['zero']['bandpass_RMS'],'candidate_higher_than_reference_percent':100*(float(np.sqrt(np.mean(bp**2)))/texture['reference']['bandpass_RMS']-1),'advisory_regressions':{'outer_rim_MAE':{'before':z['baseline_scores']['outer_rim']['mae'],'after':z['scores']['outer_rim']['mae']}},'artifacts_sha256':{n:hashlib.sha256((D/n).read_bytes()).hexdigest() for n in ['candidate-complete.npy','candidate-material.npy','coverage.npy','candidate.json','finite-filter-source-proof-FIRST.json','raw-lens-material.npy','clear-premultiplied.npy']},'claim_limits':'Ordinary coverage-normalized output filtering matches visible texture better. Not a physical roughness identification or refraction correction. Numerical native guards defined as original RMSE cohorts, SSIM, full foreground MSE and exterior MSE; auxiliary MAE changes retained.'};(D/'candidate-review.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
